import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { addConnectorRelationship, addRoom, addRoomConnector, createEmptyBuildingGraph, removeConnector } from "../src/room-entry/BuildingGraphStore.js";
describe("room-side model", () => { it("adds connectors and links", () => { let g = createEmptyBuildingGraph(); g = addRoom(g, { id: "a", name: "A", type: "other", sizeCategory: "small", connectors: [] }); g = addRoom(g, { id: "b", name: "B", type: "other", sizeCategory: "small", connectors: [] }); g = addRoomConnector(g, { id: "a-r", roomId: "a", side: "right", type: "door", position: .5 }); g = addRoomConnector(g, { id: "b-l", roomId: "b", side: "left", type: "door", position: .5 }); g = addConnectorRelationship(g, { id: "a-b", connectorA: "a-r", connectorB: "b-l", importance: "required" }); assert.equal(g.relationships.length, 1); }); it("removes dependent links", () => { const g = { schemaVersion: "2.1", id: "x", name: "X", rooms: [{ id: "a", name: "A", type: "other", sizeCategory: "small", connectors: [{ id: "p", roomId: "a", side: "top", type: "door", position: .5 }] }], relationships: [{ id: "l", connectorA: "p", connectorB: "q", importance: "required" }] }; assert.equal(removeConnector(g, "p").relationships.length, 0); }); it("rejects invalid position", () => { let g = createEmptyBuildingGraph(); g = addRoom(g, { id: "a", name: "A", type: "other", sizeCategory: "small", connectors: [] }); assert.throws(() => addRoomConnector(g, { id: "p", roomId: "a", side: "top", type: "door", position: 2 }), RangeError); }); });
